const input=$json.body??$json;
const status=String(input.performance_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const net=Number(input.net_profit??0);
const margin=Number(input.profit_margin??0);
const sample=Number(input.historical_sample_size??input.sample_size??0);
const netDelta=Number(input.net_profit_delta??0);
const marginDelta=Number(input.margin_delta??0);
let calibration_status='needs_review',next='WF-126',reason='underwriting calibration requires review',factor=1,confidence='low';
if(input.dnc===true){calibration_status='blocked_dnc';reason='DNC/contact restriction';}
else if(!dealId||!leadId||!propertyId){calibration_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(status!=='performance_record_ready'){calibration_status='performance_not_ready';next='WF-330';reason='portfolio performance record is not ready';}
else if(!Number.isFinite(net)||!Number.isFinite(margin)){calibration_status='performance_inputs_invalid';reason='realized performance inputs are invalid';}
else{
  if(sample>=20){confidence='high';if(marginDelta<-0.10||netDelta<0)factor=0.95;else if(marginDelta>0.10&&netDelta>0)factor=1.03;}
  else if(sample>=10){confidence='medium';if(marginDelta<-0.15)factor=0.97;else if(marginDelta>0.15&&netDelta>0)factor=1.02;}
  else{confidence='low';}
  calibration_status=confidence==='low'?'low_confidence_review':'calibration_ready';
  next=confidence==='low'?'WF-126':'WF-332';
  reason=confidence==='low'?'insufficient realized sample for autonomous MAO calibration':'confidence-weighted underwriting calibration completed';
}
return [{json:{...input,workflow_id:'WF-331',workflow_name:'Portfolio Performance → Underwriting Calibration & Dynamic MAO Feedback Controller',calibration_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,net_profit:net,profit_margin:margin,historical_sample_size:sample,net_profit_delta:netDelta,margin_delta:marginDelta,calibration_factor:factor,confidence,next_workflow:next,human_review_required:calibration_status!=='calibration_ready',calibration_policy:{sample_20_plus:'high confidence: 0.95 underperformance / 1.03 outperformance',sample_10_to_19:'medium confidence: 0.97 underperformance / 1.02 outperformance',sample_under_10:'low confidence: human review',asset_economics_primary:true,rule_70_secondary:true},crm_activity:{activity_type:'underwriting_calibration',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:calibration_status,calibration_factor:factor,confidence,reason}}}];
